from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack=[]
        self.void={'br','img','input','meta','link','hr','path','line','rect'}
    def handle_starttag(self,tag,a):
        if tag not in self.void: self.stack.append(tag)
    def handle_endtag(self,tag):
        if tag in self.void: return
        if self.stack and self.stack[-1]==tag: self.stack.pop()
        else: print('MISMATCH at',tag,'stack top',self.stack[-1] if self.stack else None)
p=P()
p.feed(open('sales-funnel-dashboard.html').read())
print('剩余未闭合标签:',p.stack)
print('HTML 结构解析完成')
